function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}

function canBeSumOfConsecutive(n) {
  if (n <= 0) return false;
  while (n % 2 === 0) n /= 2;
  return n > 1;
}

function knightMinSteps(n, [sr, sc], [tr, tc]) {
  const mv = [[1,2],[2,1],[-1,2],[-2,1],[1,-2],[2,-1],[-1,-2],[-2,-1]];
  const dist = Array.from({ length: n }, () => Array(n).fill(-1));
  dist[sr][sc] = 0;
  const q = [[sr, sc]];
  for (let h = 0; h < q.length; h++) {
    const [r, c] = q[h];
    if (r === tr && c === tc) return dist[r][c];
    for (const [dr, dc] of mv) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < n && nc < n && dist[nr][nc] < 0) {
        dist[nr][nc] = dist[r][c] + 1;
        q.push([nr, nc]);
      }
    }
  }
  return -1;
}

function rotateMatrix(m) {
  const n = m.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [m[i][j], m[j][i]] = [m[j][i], m[i][j]];
  for (const row of m) row.reverse();
  return m;
}

function nextGreater(a) {
  const res = new Array(a.length).fill(-1), st = [];
  for (let i = 0; i < a.length; i++) {
    while (st.length && a[st[st.length - 1]] < a[i]) res[st.pop()] = a[i];
    st.push(i);
  }
  return res;
}

class LRUCache {
  constructor(capacity) { this.cap = capacity; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return -1;
    const v = this.m.get(k);
    this.m.delete(k);
    this.m.set(k, v);
    return v;
  }
  put(k, v) {
    if (this.m.has(k)) this.m.delete(k);
    this.m.set(k, v);
    if (this.m.size > this.cap) this.m.delete(this.m.keys().next().value);
  }
}

function minPlatforms(arr, dep) {
  const a = [...arr].sort((x, y) => x - y), d = [...dep].sort((x, y) => x - y);
  let i = 0, j = 0, cur = 0, best = 0;
  while (i < a.length) {
    if (a[i] <= d[j]) { cur++; best = Math.max(best, cur); i++; }
    else { cur--; j++; }
  }
  return best;
}

function canCompleteCircuit(petrol, dist) {
  let total = 0, tank = 0, start = 0;
  for (let i = 0; i < petrol.length; i++) {
    const d = petrol[i] - dist[i];
    total += d;
    tank += d;
    if (tank < 0) { start = i + 1; tank = 0; }
  }
  return total >= 0 ? start : -1;
}

function isBalanced(s) {
  const pair = { ')': '(', ']': '[', '}': '{' }, st = [];
  for (const c of s) {
    if ('([{'.includes(c)) st.push(c);
    else if (pair[c]) { if (st.pop() !== pair[c]) return false; }
  }
  return st.length === 0;
}

function lisLength(a) {
  const t = [];
  for (const x of a) {
    let lo = 0, hi = t.length;
    while (lo < hi) {
      const m = (lo + hi) >> 1;
      if (t[m] < x) lo = m + 1; else hi = m;
    }
    t[lo] = x;
  }
  return t.length;
}

function missingNumber(a) {
  const n = a.length + 1;
  let x = 0;
  for (let i = 1; i <= n; i++) x ^= i;
  for (const v of a) x ^= v;
  return x;
}
